def solve(inputs: dict) -> float:
    from math import gcd

    rems = inputs['rems']
    mods = inputs['mods']

    # Extended GCD
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd_val, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd_val, x, y

    # Modular inverse
    def mod_inverse(a, m):
        gcd_val, x, _ = extended_gcd(a % m, m)
        if gcd_val != 1:
            return None
        return (x % m + m) % m

    # Chinese Remainder Theorem
    def crt(remainders, moduli):
        # Check that moduli are pairwise coprime
        for i in range(len(moduli)):
            for j in range(i + 1, len(moduli)):
                if gcd(moduli[i], moduli[j]) != 1:
                    # Not coprime, use generalized CRT
                    pass

        # Standard CRT
        total_mod = 1
        for m in moduli:
            total_mod *= m

        result = 0
        for i in range(len(remainders)):
            Mi = total_mod // moduli[i]
            yi = mod_inverse(Mi, moduli[i])
            result += remainders[i] * Mi * yi

        return result % total_mod

    x = crt(rems, mods)
    return float(x)

